using backend.Models;
using Microsoft.EntityFrameworkCore;

namespace backend.Data;

public class CrmDbContext(DbContextOptions<CrmDbContext> options) : DbContext(options)
{
    public DbSet<Role> Roles => Set<Role>();
    public DbSet<User> Users => Set<User>();
    public DbSet<Lead> Leads => Set<Lead>();
    public DbSet<FollowUp> FollowUps => Set<FollowUp>();
    public DbSet<FollowUpProof> FollowUpProofs => Set<FollowUpProof>();
    public DbSet<Customer> Customers => Set<Customer>();
    public DbSet<Project> Projects => Set<Project>();
    public DbSet<SubGroup> SubGroups => Set<SubGroup>();
    public DbSet<Invoice> Invoices => Set<Invoice>();
    public DbSet<Payment> Payments => Set<Payment>();
    public DbSet<Commission> Commissions => Set<Commission>();
    public DbSet<CommissionRule> CommissionRules => Set<CommissionRule>();
    public DbSet<VehicleBooking> VehicleBookings => Set<VehicleBooking>();
    public DbSet<Vehicle> Vehicles => Set<Vehicle>();
    public DbSet<LeadAutomationSettings> LeadAutomationSettings => Set<LeadAutomationSettings>();
    public DbSet<LeadReturn> LeadReturns => Set<LeadReturn>();
    public DbSet<EmployeeLocation> EmployeeLocations => Set<EmployeeLocation>();
    public DbSet<AppNotification> AppNotifications => Set<AppNotification>();
    public DbSet<PermissionGroup> PermissionGroups => Set<PermissionGroup>(); public DbSet<Permission> Permissions => Set<Permission>();
    public DbSet<RolePermission> RolePermissions => Set<RolePermission>(); public DbSet<UserPermission> UserPermissions => Set<UserPermission>();
    public DbSet<FinancialAgreement> FinancialAgreements => Set<FinancialAgreement>(); public DbSet<EmiInstallment> EmiInstallments => Set<EmiInstallment>();
    public DbSet<FinancialAuditLog> FinancialAuditLogs => Set<FinancialAuditLog>(); public DbSet<AuditLog> AuditLogs => Set<AuditLog>(); public DbSet<NotificationSettings> NotificationSettings => Set<NotificationSettings>();
    public DbSet<DailyWorkReport> DailyWorkReports => Set<DailyWorkReport>();
    public DbSet<MonthlySalesTarget> MonthlySalesTargets => Set<MonthlySalesTarget>();
    public DbSet<MonthlyCollection> MonthlyCollections => Set<MonthlyCollection>();
    public DbSet<CustomerDue> CustomerDues => Set<CustomerDue>();
    public DbSet<SalesGroup> SalesGroups => Set<SalesGroup>();
    public DbSet<SalesTeam> SalesTeams => Set<SalesTeam>();
    public DbSet<SalesGroupTarget> SalesGroupTargets => Set<SalesGroupTarget>();
    public DbSet<SalesTeamTarget> SalesTeamTargets => Set<SalesTeamTarget>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Role>().HasIndex(x => x.Name).IsUnique();
        modelBuilder.Entity<User>().HasIndex(x => x.Email).IsUnique();
        modelBuilder.Entity<User>().Property(x => x.LocationTrackingEnabled).HasDefaultValue(true);
        modelBuilder.Entity<Customer>().HasIndex(x => x.LeadId).IsUnique();
        modelBuilder.Entity<Invoice>().HasIndex(x => x.InvoiceNumber).IsUnique();
        modelBuilder.Entity<Payment>().HasIndex(x => x.CollectionNumber).IsUnique();
        modelBuilder.Entity<SubGroup>().HasIndex(x => x.Name).IsUnique();
        modelBuilder.Entity<Project>().HasOne(x => x.SubGroup).WithMany(x => x.Projects).HasForeignKey(x => x.SubGroupId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<Customer>().HasOne(x => x.Project).WithMany().HasForeignKey(x => x.ProjectId).OnDelete(DeleteBehavior.SetNull);
        modelBuilder.Entity<Lead>().HasOne(x => x.Project).WithMany().HasForeignKey(x => x.ProjectId).OnDelete(DeleteBehavior.SetNull);
        modelBuilder.Entity<Lead>().HasOne(x => x.PreviousCustomer).WithMany().HasForeignKey(x => x.PreviousCustomerId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<Customer>().HasOne(x => x.Lead).WithMany().HasForeignKey(x => x.LeadId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<Commission>().HasOne(x => x.Payment).WithMany().HasForeignKey(x => x.PaymentId);
        modelBuilder.Entity<Payment>().HasOne(x => x.VerifiedBy).WithMany().HasForeignKey(x => x.VerifiedById).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<VehicleBooking>().HasOne(x => x.SalesExecutive).WithMany().HasForeignKey(x => x.SalesExecutiveId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<VehicleBooking>().HasOne(x => x.ReviewedBy).WithMany().HasForeignKey(x => x.ReviewedById).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<VehicleBooking>().HasOne(x => x.Customer).WithMany().HasForeignKey(x => x.CustomerId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<VehicleBooking>().HasOne(x => x.Lead).WithMany().HasForeignKey(x => x.LeadId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<VehicleBooking>().HasOne(x => x.Project).WithMany().HasForeignKey(x => x.ProjectId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<VehicleBooking>().HasOne(x => x.Vehicle).WithMany().HasForeignKey(x => x.VehicleId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<Vehicle>().HasIndex(x => x.RegistrationNumber).IsUnique();
        modelBuilder.Entity<LeadAutomationSettings>().Property(x => x.UnassignAfterHours).HasPrecision(10, 4);
        modelBuilder.Entity<LeadAutomationSettings>().Property(x => x.ReminderIntervalHours).HasPrecision(10, 4);
        modelBuilder.Entity<LeadReturn>().HasOne(x => x.Lead).WithMany().HasForeignKey(x => x.LeadId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<LeadReturn>().HasOne(x => x.SalesExecutive).WithMany().HasForeignKey(x => x.SalesExecutiveId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<EmployeeLocation>().HasOne(x => x.User).WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Cascade);
        modelBuilder.Entity<EmployeeLocation>().HasIndex(x => new { x.UserId, x.RecordedAtUtc });
        modelBuilder.Entity<AppNotification>().HasOne(x => x.User).WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Cascade);
        modelBuilder.Entity<AppNotification>().HasIndex(x => new { x.UserId, x.EventKey }).IsUnique();
        modelBuilder.Entity<AppNotification>().HasIndex(x => new { x.UserId, x.IsRead, x.CreatedAt });
        modelBuilder.Entity<PermissionGroup>().HasIndex(x => x.Name).IsUnique(); modelBuilder.Entity<Permission>().HasIndex(x => x.Code).IsUnique();
        modelBuilder.Entity<RolePermission>().HasKey(x => new { x.RoleId, x.PermissionId }); modelBuilder.Entity<UserPermission>().HasKey(x => new { x.UserId, x.PermissionId });
        modelBuilder.Entity<FinancialAgreement>().HasIndex(x => x.CustomerId).IsUnique(); modelBuilder.Entity<FinancialAgreement>().Property(x => x.TotalAgreedAmount).HasPrecision(18, 2); modelBuilder.Entity<FinancialAgreement>().Property(x => x.BookingAmount).HasPrecision(18, 2); modelBuilder.Entity<FinancialAgreement>().Property(x => x.DownPaymentAmount).HasPrecision(18, 2); modelBuilder.Entity<FinancialAgreement>().Property(x => x.MonthlyEmiAmount).HasPrecision(18, 2);
        modelBuilder.Entity<EmiInstallment>().HasIndex(x => new { x.FinancialAgreementId, x.InstallmentNumber }).IsUnique(); modelBuilder.Entity<EmiInstallment>().Property(x => x.ExpectedAmount).HasPrecision(18, 2); modelBuilder.Entity<EmiInstallment>().Property(x => x.PaidAmount).HasPrecision(18, 2);
        modelBuilder.Entity<Payment>().Property(x => x.Amount).HasPrecision(18, 2); modelBuilder.Entity<Payment>().HasIndex(x => x.IdempotencyKey).IsUnique();
        modelBuilder.Entity<Customer>().HasIndex(x => x.FileId).IsUnique();
        modelBuilder.Entity<DailyWorkReport>().HasIndex(x => new { x.SalesExecutiveId, x.WorkDate }).IsUnique();
        modelBuilder.Entity<DailyWorkReport>().HasOne(x => x.SalesExecutive).WithMany().HasForeignKey(x => x.SalesExecutiveId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<MonthlySalesTarget>().HasIndex(x => new { x.SalesExecutiveId, x.Month }).IsUnique();
        modelBuilder.Entity<MonthlySalesTarget>().Property(x => x.MinimumCollectionAmount).HasPrecision(18, 2);
        modelBuilder.Entity<MonthlySalesTarget>().HasOne(x => x.SalesExecutive).WithMany().HasForeignKey(x => x.SalesExecutiveId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<MonthlySalesTarget>().HasOne(x => x.UpdatedBy).WithMany().HasForeignKey(x => x.UpdatedById).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<MonthlyCollection>().HasIndex(x => new { x.SalesExecutiveId, x.Month }).IsUnique();
        modelBuilder.Entity<MonthlyCollection>().Property(x => x.Amount).HasPrecision(18, 2);
        modelBuilder.Entity<MonthlyCollection>().HasOne(x => x.SalesExecutive).WithMany().HasForeignKey(x => x.SalesExecutiveId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<MonthlyCollection>().HasOne(x => x.RecordedBy).WithMany().HasForeignKey(x => x.RecordedById).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<CustomerDue>().HasIndex(x => new { x.CustomerId, x.Month }).IsUnique();
        modelBuilder.Entity<CustomerDue>().Property(x => x.Amount).HasPrecision(18, 2);
        modelBuilder.Entity<CustomerDue>().HasOne(x => x.Customer).WithMany().HasForeignKey(x => x.CustomerId).OnDelete(DeleteBehavior.Cascade);
        modelBuilder.Entity<CustomerDue>().HasOne(x => x.RecordedBy).WithMany().HasForeignKey(x => x.RecordedById).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<SalesGroup>().HasIndex(x => x.Name).IsUnique();
        modelBuilder.Entity<SalesGroup>().HasIndex(x => x.GroupLeaderId).IsUnique();
        modelBuilder.Entity<SalesGroup>().HasOne(x => x.GroupLeader).WithMany().HasForeignKey(x => x.GroupLeaderId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<SalesTeam>().HasIndex(x => new { x.SalesGroupId, x.Name }).IsUnique();
        modelBuilder.Entity<SalesTeam>().HasOne(x => x.SalesGroup).WithMany().HasForeignKey(x => x.SalesGroupId).OnDelete(DeleteBehavior.Cascade);
        modelBuilder.Entity<SalesTeam>().HasOne(x => x.ParentTeam).WithMany().HasForeignKey(x => x.ParentTeamId).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<SalesTeam>().HasOne(x => x.TeamLeader).WithMany().HasForeignKey(x => x.TeamLeaderId).OnDelete(DeleteBehavior.SetNull);
        modelBuilder.Entity<User>().HasOne(x => x.SalesTeam).WithMany().HasForeignKey(x => x.SalesTeamId).OnDelete(DeleteBehavior.SetNull);
        modelBuilder.Entity<SalesGroupTarget>().HasIndex(x => new { x.SalesGroupId, x.Month }).IsUnique();
        modelBuilder.Entity<SalesGroupTarget>().Property(x => x.CollectionTarget).HasPrecision(18, 2);
        modelBuilder.Entity<SalesGroupTarget>().HasOne(x => x.UpdatedBy).WithMany().HasForeignKey(x => x.UpdatedById).OnDelete(DeleteBehavior.Restrict);
        modelBuilder.Entity<SalesTeamTarget>().HasIndex(x => new { x.SalesTeamId, x.Month }).IsUnique();
        modelBuilder.Entity<SalesTeamTarget>().Property(x => x.CollectionTarget).HasPrecision(18, 2);
        modelBuilder.Entity<SalesTeamTarget>().HasOne(x => x.UpdatedBy).WithMany().HasForeignKey(x => x.UpdatedById).OnDelete(DeleteBehavior.Restrict);
    }
}
